 void VerifyWorkspaceEnhancements(string folder){var before=DayDashboard.CloneLayout(store.Value.settings.HomeBlocks);dialogProbe=delegate(Window w){var input=LogicalControls<TextBox>(w).First();input.Text="Disposition UI";ClickWizard(w,"Enregistrer l’accueil actuel");return true;};try{SavedLayouts();}finally{dialogProbe=null;}if(!store.Value.settings.enhancements.layouts.Any(l=>l.name=="Disposition UI"))throw new Exception("Sauvegarde disposition par bouton");store.Value.tasks.Add(new WorkTask{id="review-ui",title="Tâche du bilan UI",project="Personnel",status="doing",priority="Normale",due=DateTime.Today.ToString("yyyy-MM-dd")});dialogProbe=delegate(Window w){var check=LogicalControls<CheckBox>(w).First(c=>Convert.ToString(c.Content)=="Tâche du bilan UI");check.IsChecked=true;check.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));LogicalControls<TextBox>(w).First().Text="Demain : préparer les plans";ClickWizard(w,"Enregistrer le bilan");return true;};try{DailyReviewDialog();}finally{dialogProbe=null;}if(store.Value.tasks.First(t=>t.id=="review-ui").due!=DateTime.Today.AddDays(1).ToString("yyyy-MM-dd")||new Store(store.Root).Value.settings.enhancements.reviews.Count==0)throw new Exception("Bilan UI non conservé");string document=Path.Combine(folder,"session-test.txt");File.WriteAllText(document,"session");var oldSession=store.Value.settings.enhancements.session;store.Value.settings.enhancements.session=new SavedWorkspaceSession{page="Documents locaux",document=document,sideDocument=document,tabs=new System.Collections.Generic.List<SavedWorkspaceTab>{new SavedWorkspaceTab{page="Documents locaux",document=document},new SavedWorkspaceTab{page="Mes tâches"}}};RestoreWorkspaceSession(false,true);if(selected!="Documents locaux"||openDocument!=document||sideDocument!=document||openTabs.Count!=2)throw new Exception("Onglets ou panneaux non restaurés");store.Value.settings.enhancements.session=oldSession;selected="Aujourd’hui";openDocument=sideDocument="";store.Value.settings.HomeBlocks=before;store.Save();Go("Aujourd’hui");PreviewSized(Path.Combine(folder,"Accueil-outils.png"),1280,1000);if(!LogicalControls<Button>(this).Any(b=>Convert.ToString(b.Content)=="Dispositions")||!LogicalControls<Button>(this).Any(b=>Convert.ToString(b.Content)=="Connexions"))throw new Exception("Nouveaux outils absents de l’accueil");dialogProbe=delegate(Window w){if(!LogicalControls<Button>(w).Any(b=>Convert.ToString(b.Content)=="Tester les connexions"))throw new Exception("Diagnostic absent");return true;};try{ConnectionDiagnostics();}finally{dialogProbe=null;}File.WriteAllText(Path.Combine(folder,"ENHANCEMENTS_UI_PASS.txt"),"PASS: actual layout save; review button and selected task postponement; session tabs and side document restore; accessible home tools; diagnostic controls. External OAuth services are not contacted by tests.");}
